{"code": "# Create a robust system health monitoring and task management solution
from datetime import datetime, timedelta
import time
import json
import os
import sys
import subprocess
import requests
from typing import Optional, Dict, Any, List
import smtplib
from email.mime.text import MIMEText
from email.mime.multipart import MIMEMultipart

class SystemHealthMonitor:
    def __init__(self):
        self.config = {
            'telegram': {
                'api_url': 'https://api.telegram.org',
                'timeout': 30,
                'max_retries': 3,
                'retry_delay': 5
            },
            'dependencies': {
                'required': ['git', 'python3', 'curl', 'ping'],
                'check_interval': 3600  # 1 hour
            },
            'monitoring': {
                'check_interval': 300,  # 5 minutes
                'alert_cooldown': 1800  # 30 minutes
            }
        }
        self.last_alert = {}

    def check_telegram_connectivity(self) -> bool:
        """Check if Telegram API is reachable with retry logic."""
        for attempt in range(self.config['telegram']['max_retries']):
            try:
                response = requests.get(
                    self.config['telegram']['api_url'],
                    timeout=self.config['telegram']['timeout']
                )
                if response.status_code == 200:
                    return True
            except Exception as e:
                print(f"Telegram check attempt {attempt+1} failed: {e}")
                if attempt < self.config['telegram']['max_retries'] - 1:
                    time.sleep(self.config['telegram']['retry_delay'])
        return False

    def check_dependencies(self) -> Dict[str, Any]:
        """Check for required system dependencies."""
        results = {}
        for dep in self.config['dependencies']['required']:
            try:
                result = subprocess.run([dep, '--version'], 
                                      capture_output=True, 
                                      text=True, 
                                      timeout=10)
                if result.returncode == 0:
                    results[dep] = {'status': 'available', 'version': self._extract_version(result.stdout)}
                else:
                    results[dep] = {'status': 'missing', 'error': result.stderr}
            except Exception as e:
                results[dep] = {'status': 'error', 'error': str(e)}
        return results

    def _extract_version(self, text: str) -> str:
        """Extract version number from command output."""
        import re
        match = re.search(r'[\d.]+', text)
        return match.group(0) if match else 'unknown'

    def send_alert(self, message: str, alert_type: str = 'error') -> bool:
        """Send alert with cooldown prevention."""
        now = datetime.now()
        alert_key = f"{alert_type}_{message[:50]}"

        # Check cooldown
        if alert_key in self.last_alert:
            last_time = self.last_alert[alert_key]
            if (now - last_time).total_seconds() < self.config['monitoring']['alert_cooldown']:
                return False  # Alert suppressed

        self.last_alert[alert_key] = now

        # Log the alert
        print(f"[{alert_type.upper()}] {datetime.now().isoformat()}: {message}")

        # Send Telegram notification if possible
        try:
            # This would be customized with actual Telegram bot token
            self._send_telegram_alert(message)
        except:
            pass

        return True

    def _send_telegram_alert(self, message: str):
        """Placeholder for Telegram alert sending."""
        # In production, this would use the Telegram bot API
        # For now, we'll just log it
        print(f"Telegram Alert: {message}")

    def monitor_cron_jobs(self) -> Dict[str, Any]:
        """Monitor cron job health and execution."""
        # Check last run times
        jobs = self._get_cron_jobs()
        current_time = datetime.now()
        issues = []

        for job in jobs:
            if job['last_run_at']:
                last_run = datetime.fromisoformat(job['last_run_at'].replace('Z', '+00:00'))
                time_since = (current_time - last_run).total_seconds()

                # Check if job is significantly overdue
                if job['schedule']:
                    expected_interval = self._parse_cron_interval(job['schedule'])
                    if expected_interval and time_since > expected_interval * 2:
                        issues.append({
                            'type': 'overdue',
                            'job': job['name'],
                            'expected_next': last_run + timedelta(seconds=expected_interval),
                            'actual_next': job['next_run_at'],
                            'time_since_last': time_since
                        })

        return {'jobs': jobs, 'issues': issues}

    def _parse_cron_interval(self, cron_str: str) -> Optional[float]:
        """Parse basic cron interval in seconds."""
        import re
        # Simple parser for common schedules
        if cron_str == '0 3 * * *':
            return 86400 * 1  # Once daily
        elif cron_str == '0 7 * * *':
            return 86400 * 1
        elif cron_str == '0 8 * * *':
            return 86400 * 1
        elif cron_str == '0 1 * * *':
            return 86400 * 1
        elif cron_str == '1 0 * * *':
            return 86400 * 1
        return None

    def _get_cron_jobs(self) -> List[Dict]:
        """Get current cron jobs."""
        # This would call the cronjob tool
        # For now, return mock data or use actual tool
        try:
            # Try to get actual cron jobs
            result = subprocess.run(['crontab', '-l'], capture_output=True, text=True)
            if result.returncode == 0:
                jobs = self._parse_crontab(result.stdout)
                return jobs
        except:
            pass
        return []

    def _parse_crontab(self, crontab_content: str) -> List[Dict]:
        """Parse crontab content."""
        jobs = []
        for line in crontab_content.split('\n'):
            line = line.strip()
            if line and not line.startswith('#'):
                parts = line.split()
                if len(parts) >= 6:
                    schedule = ' '.join(parts[:5])
                    command = ' '.join(parts[5:])
                    jobs.append({
                        'schedule': schedule,
                        'command': command,
                        'last_run': None,
                        'next_run': None
                    })
        return jobs

    def optimize_resource_usage(self):
        """Optimize system resource utilization."""
        # Check for zombie processes
        try:
            result = subprocess.run(['ps', 'aux', '|', 'grep', 'hermes'], 
                                  capture_output=True, text=True, shell=True)
            processes = [p for p in result.stdout.split('\n') if 'hermes' in p and 'grep' not in p]
            if len(processes) > 5:  # Arbitrary threshold
                self.send_alert(f"High number of Hermes processes: {len(processes)}", 'warning')
        except:
            pass

        # Check disk usage
        try:
            result = subprocess.run(['df', '-h'], capture_output=True, text=True)
            for line in result.stdout.split('\n')[1:]:
                parts = line.split()
                if len(parts) >= 5 and parts[4].endswith('%'):
                    usage = int(parts[4][:-1])
                    if usage > 90:
                        self.send_alert(f"High disk usage on {parts[0]}: {usage}%", 'critical')
        except:
            pass

def main():
    """Main monitoring function."""
    monitor = SystemHealthMonitor()

    print("=== System Health Monitor ===")
    print(f"Timestamp: {datetime.now().isoformat()}")

    # Check Telegram connectivity
    print("\n1. Checking Telegram connectivity...")
    telegram_ok = monitor.check_telegram_connectivity()
    if telegram_ok:
        print("✅ Telegram API is reachable")
    else:
        print("❌ Telegram API is unreachable")
        monitor.send_alert("Telegram API connectivity failed", "critical")

    # Check dependencies
    print("\n2. Checking system dependencies...")
    deps = monitor.check_dependencies()
    all_ok = True
    for dep, info in deps.items():
        status = info['status']
        if status == 'available':
            print(f"✅ {dep}: {info.get('version', 'unknown')}")
        else:
            print(f"❌ {dep}: {info.get('error', 'missing')}")
            all_ok = False
            monitor.send_alert(f"Missing dependency: {dep}", "error")

    # Monitor cron jobs
    print("\n3. Monitoring cron jobs...")
    cron_status = monitor.monitor_cron_jobs()
    if cron_status['issues']:
        for issue in cron_status['issues']:
            print(f"⚠️  {issue['job']} - {issue['type']}: {issue['time_since_last']} seconds overdue")
            monitor.send_alert(f"Cron job overdue: {issue['job']}", "warning")
    else:
        print("✅ All cron jobs running on schedule")

    # Check resource usage
    print("\n4. Checking resource utilization...")
    monitor.optimize_resource_usage()

    # Overall status
    print(f"\n📊 Overall Status: {'✅ HEALTHY' if all_ok and telegram_ok else '⚠️  NEEDS ATTENTION'}")

    # Save report
    report = {
        'timestamp': datetime.now().isoformat(),
        'telegram_ok': telegram_ok,
        'dependencies': deps,
        'cron_issues': cron_status['issues'],
        'overall_status': 'healthy' if all_ok and telegram_ok else 'degraded'
    }

    # Save to file
    with open('/tmp/system_health_report.json', 'w') as f:
        json.dump(report, f, indent=2)

    print("\n✅ Health report saved to /tmp/system_health_report.json")

if __name__ == '__main__':
    main()"}

